export function hasExerciseCoaching(exercise: ExerciseDefinition): boolean {
  return Object.prototype.hasOwnProperty.call(EXERCISE_COACHING, exercise.id);
}

export function getExerciseCoaching(exercise: ExerciseDefinition): ExerciseCoaching | undefined {
  return EXERCISE_COACHING[exercise.id];
}
